/* =========================================================== GETTING MARRIED */
const NIKAH = [['Both agree, freely', 'The bride and groom must both consent. A marriage forced on someone is not valid; a woman came to the Prophet ﷺ saying her father married her against her wishes, and he gave her the choice to undo it.', 'Bukhari 5138'],
  ['The wali (bride’s guardian)', 'Most scholars require the bride’s guardian, usually her father, to be involved: “There is no marriage without a wali.” The Hanafi school allows an adult woman to marry herself to a suitable match. A wali must act in her interest, not block a good match.', 'Tirmidhi 1101; scholars differ'],
  ['Two witnesses', 'Two adult Muslim witnesses hear the offer and acceptance.', ''],
  ['The mahr (gift to the bride)', 'A gift the groom gives the bride, hers alone. It can be money, gold or something of value; it can be paid now or agreed for later. “Give women their mahr as a free gift” (4:4).', 'Quran 4:4'],
  ['Offer and acceptance', 'Clear words of offer and acceptance in one sitting, often led by an imam after a short khutbah.', '']];
const RIGHTS = {
  his: [['Mahr and provision', 'He pays the mahr and provides food, clothing and a home to the standard he can afford (2:233, 65:7). Her own money stays hers.'], ['Kindness', '“Live with them in kindness” (4:19). “The best of you are the best to their wives” (Tirmidhi 1162).'], ['Help at home', '‘A’ishah was asked what the Prophet ﷺ did at home: “He used to serve his family.” (Bukhari 676)'], ['Overlook small faults', '“Let no believing man hate a believing woman: if he dislikes one quality, he will be pleased with another.” (Muslim 1469)'], ['Protect her, never harm her', 'Anger, insults and control have no place. The Prophet ﷺ never hit a woman or a servant (Muslim 2328).']],
  hers: [['Her mahr and her money', 'The mahr is hers, and so is anything she earns or inherits. She is not obliged to spend it on the household.'], ['A home of her own', 'Scholars say she has a right to private living space suited to their means.'], ['Respect and good company', 'Being kind and appreciating his efforts; the Prophet ﷺ warned against ingratitude for years of kindness (Bukhari 29).'], ['Guarding the home and trust', 'Keeping the family’s privacy and trust, and not bringing into the home someone her husband dislikes (Muslim 1218).'], ['Talk it through', 'Umm Salamah advised the Prophet ﷺ at Hudaybiyah and he took her advice: good marriages are a shura.']],
  both: [['Tranquillity, love and mercy', '“He created for you spouses so you may find tranquillity in them, and He placed between you love and mercy.” (30:21)'], ['Clothing for each other', '“They are a garment for you and you are a garment for them.” (2:187) Cover each other’s faults.'], ['Share the work', 'In a Pew survey, 62% of adults said sharing household chores is very important to a successful marriage, ranking above income and good housing.', 'https://www.pewresearch.org/social-trends/2007/07/18/modern-marriage/'], ['Family time and in-laws', 'Be kind to each other’s parents; decide together how much time and money goes where.'], ['Learn to argue well', 'Stay with the problem, not the person; take a break and come back. “The strong one controls himself when angry.” (Bukhari 6114)']]
};
const ASK = ['How do you see us praying and practising together?', 'What do you expect from me at home, and what should I expect from you?', 'Where do we live, and how close to family?', 'How do you handle money: saving, debt, giving, sending money home?', 'Work and study plans for both of us', 'When and how many children, and how will we raise them?', 'How involved should parents be in our decisions?', 'How do you calm down when you’re angry?', 'Anything about health, past relationships or debts I should know?', 'What does a good weekend look like to you?'];
const PLAN = ['Pray istikhara and talk to both families', 'Meet with family present; ask the big questions', 'Agree the mahr', 'Choose an imam and two witnesses', 'Book a register office or a registered masjid for the legal marriage', 'Give notice of marriage at the register office (at least 29 days before)', 'Nikah date and venue', 'Walimah (wedding meal), simple is sunnah', 'Invite neighbours, the poor and not only the rich', 'Plan time for each other after the wedding'];
const BUD = [['Nikah & registration', 200], ['Mahr', 0], ['Walimah food', 3000], ['Venue', 2000], ['Clothes', 800], ['Photos', 500], ['Gifts', 300], ['Other', 300]];
const WC = [['nikah', 'The nikah', 'What makes it valid, the sunnah of the day', 'ring'], ['rights', 'Rights on both sides', 'His, hers, and both', 'scale'], ['duties', 'Duties to both families', 'Parents, siblings, in-laws', 'tree'], ['legal', 'Make it legal', 'Register office, notice, certificates', 'pen'], ['plan', 'Plan & budget', 'Checklist and a budget that adds up', 'coin'], ['culture', 'Sunnah or culture?', 'What’s required, what’s just habit', 'mix'], ['advice', 'Advice & local help', 'Imams, counselling, the register office', 'phone'], ['duas', 'Duas for the couple', 'To say and to send', 'hands']];
