    if (n === RQS.length) { const ar = Object.keys(RAREA).map(k => { const ix = RQS.map((r, i) => r[0] === k ? i : -1).filter(i => i >= 0), v = ix.reduce((a, i) => a + A[i], 0) / (ix.length * 2); return [k, v]; }), low = ar.filter(x => x[1] < .75).sort((a, b) => a[1] - b[1]);
      h += `<div class="mr-res"><b>Your readiness map</b>${ar.map(([k, v]) => `<div class="mr-bar"><span>${RAREA[k][0]}</span><i><u style="width:${Math.round(v * 100)}%"></u></i><em>${Math.round(v * 100)}%</em></div>`).join('')}
        <p>${low.length ? 'Start with: ' + low.slice(0, 2).map(x => RAREA[x[0]][0]).join(' and ') + '. Nobody is fully ready; aim for “ready enough, and growing”.' : 'MashaAllah: you’re in a good place. Keep growing, and start the conversations with your family.'}</p>
        <div class="lf-row2">${[...new Set(low.map(x => RAREA[x[0]][1]))].slice(0, 2).map(t => `<button type="button" class="lfg-btn" data-tab="tab:${t}">${esc(WL.find(c => c[0] === t)[1])}</button>`).join('')}<button type="button" class="lfg-btn" data-rqreset>Start again</button></div></div>`; }
