      <div class="lf-ang">${[['q', 'If they are poor, Allah will enrich them from His bounty.', 'Quran 24:32', QU(24, 32)], ['q', 'Let each spend according to their means.', 'Quran 65:7', QU(65, 7)], ['sc', 'The husband provides the home, food and clothing. A wife’s own money stays hers. Your duty to your own parents continues after marriage, so build it into the budget.'], ['c', 'Couples often say the cheapest wedding they ever went to was also the happiest. Many start by renting a room or living with family for a year to save.']].map(([k, t, ref, link]) => `<div class="lf-ag" style="--lc:${LENS[k][1]}"><em>${LENS[k][0]}</em><p>${esc(t)}</p>${ref ? (link ? `<a href="${link}" target="_blank" rel="noopener">${esc(ref)} ↗</a>` : `<small>${esc(ref)}</small>`) : ''}</div>`).join('')}</div>
