const WHO = [['parent', 'A parent'], ['spouse', 'A husband or wife'], ['child', 'A child'], ['baby', 'A baby or pregnancy'], ['sibling', 'A brother or sister'], ['grand', 'A grandparent'], ['friend', 'A friend'], ['sudden', 'Sudden or tragic death']];
const GRIEF_ALL = [['q', '“We will surely test you with something of fear and hunger and loss of wealth, lives and fruits. Give good news to the patient: those who, when disaster strikes, say: To Allah we belong and to Him we return.”', 'Quran 2:155–156'],
  ['h', 'When the Prophet’s son Ibrahim died, his eyes filled with tears. He said: “The eyes shed tears and the heart grieves, but we say only what pleases our Lord. We are saddened by your parting, O Ibrahim.” Crying is not a lack of faith.', 'Bukhari 1303'],
  ['h', 'Patience is at the first strike of grief.', 'Bukhari 1283'],
  ['s', 'In one year the Prophet ﷺ lost his wife Khadijah and his uncle Abu Talib. It is remembered as the Year of Sorrow; soon after came the Night Journey, a sign that Allah sees grief.', 'Seerah'],
  ['p', 'Grief comes and goes: the dual process model describes moving between missing the person and getting on with daily life. Both are healthy.', 'Stroebe & Schut, 1999', 'https://www.goodtherapy.org/learn-about-therapy/issues/grief'],
  ['p', 'Most people adapt with time. About one in ten bereaved adults develop prolonged grief that gets in the way of daily life for many months, and help works.', 'Lundorff et al., 2017', 'https://pubmed.ncbi.nlm.nih.gov/28167398/'],
  ['c', 'Let people bring food and sit with you. Keep one small routine: a walk, a salah in the masjid. It’s fine to say you’re not okay.', '']];
const GRIEF = {
  parent: [['q', 'Your Lord has decreed kindness to parents. Say: My Lord, have mercy on them as they raised me when I was small.', 'Quran 17:23–24'], ['h', 'When a person dies their deeds end except three: ongoing charity, knowledge that benefits, or a righteous child who prays for them.', 'Muslim 1631'], ['h', 'A man asked what he could still do for his parents after they died. The Prophet ﷺ said: pray for them, seek forgiveness for them, fulfil their promises, keep ties with their relatives and honour their friends.', 'Abu Dawud 5142 (scholars differ on its strength)'], ['p', 'Losing a parent can feel like losing your past: who remembers you as a child now? Telling their stories helps.', ''], ['c', 'Visit their friends, cook their recipes, keep giving to the causes they loved.', '']],
  spouse: [['q', 'Widows wait four months and ten days (‘iddah), a time protected for mourning and care.', 'Quran 2:234'], ['s', 'Years after Khadijah died, the Prophet ﷺ still sent gifts to her friends and spoke of her with love.', 'Bukhari 3818'], ['h', 'Umm Salamah said the dua the Prophet ﷺ taught when her husband died, wondering who could be better than Abu Salamah. Allah replaced him with the Prophet ﷺ himself.', 'Muslim 918'], ['p', 'Losing a partner affects sleep, appetite and health. See your GP if you’re struggling, and accept practical help with paperwork and money.', ''], ['c', 'Ask a trusted friend to sort the admin with you. Don’t make big decisions, like selling the house, in the first months.', '']],
  child: [['h', 'When a believer’s child dies and they praise Allah, Allah says: build for My servant a house in Paradise and call it the House of Praise.', 'Tirmidhi 1021'], ['h', 'Any Muslim who loses three children before puberty, Allah will enter them into Paradise by His mercy. A woman asked: and two? He said: and two.', 'Bukhari 1248, 101'], ['p', 'Parents often grieve differently: one talks, the other works. Neither is wrong. Siblings need explaining too, in simple words.', ''], ['c', 'Keep their name in your duas and in the family. Many families give a sadaqah jariyah in the child’s name.', '']],
  baby: [['h', 'Children who die young are in the care of Ibrahim (as) in Paradise.', 'Bukhari 7047'], ['sc', 'Scholars say a baby who dies is in Paradise, and many say a miscarried baby after the soul is given (around 120 days) is named, washed and prayed over. Ask your imam what applies.', ''], ['p', 'Pregnancy loss is real grief, even if few people knew. Fathers grieve too. Tommy’s and the Miscarriage Association offer support.', ''], ['c', 'Give the baby a name. It’s okay to keep a memory box with scans and small things.', '']],
  sibling: [['q', 'Musa asked Allah to strengthen him with his brother Harun: “We will strengthen your arm through your brother.”', 'Quran 28:35'], ['p', 'Losing a sibling can feel overlooked: people ask after your parents. Your grief counts too.', ''], ['c', 'Look after their children if they had any; keep their friendships going.', '']],
  grand: [['h', 'Keeping family ties extends your life and increases your provision.', 'Bukhari 5986'], ['p', 'Children often lose their first close person when a grandparent dies. Let them come to the janazah if they want, and answer questions honestly.', ''], ['c', 'Write down their stories and recipes while family still remembers them.', '']],
  friend: [['h', 'Seven will be shaded on the Day with no shade but His, including two people who loved each other for Allah’s sake.', 'Bukhari 660'], ['p', 'Friends’ grief is often not recognised. Go to the janazah, visit the family and let yourself mourn.', ''], ['c', 'Do something good in their name with your friendship group: a fundraiser, a Quran khatm.', '']],
  sudden: [['h', 'A death by plague, drowning, a collapsed building, or an illness of the stomach is counted as martyrdom.', 'Bukhari 2829'], ['p', 'Sudden or violent deaths can bring shock, flashbacks and anger. These are normal reactions; if they don’t ease after a few weeks, ask your GP about trauma support.', ''], ['uk', 'Sudden deaths are usually referred to the coroner, which can delay burial. Ask for an urgent decision on religious grounds: coroners have guidance for this.', 'Chief Coroner’s Guidance No. 28', 'https://www.judiciary.uk/guidance-and-resources/chief-coroners-guidance-no-28-report-of-death-to-the-coroner-decision-making-and-expedited-decisions/'], ['c', 'Let one person in the family handle calls from the police, coroner and press.', '']]
};
const NOW = [['Straight away', 'Close their eyes and make dua for them. Say: Inna lillahi wa inna ilayhi raji‘un. Call the GP (at home), or the ward staff (in hospital), or 999 if it was sudden.'], ['Hours', 'Call a Muslim funeral director. They contact the doctor, collect the deceased and arrange the ghusl, kafan and burial plot.'], ['Paperwork', 'A doctor and the medical examiner issue the cause of death. Register the death within 5 days; many councils offer an urgent faith service so burial is not delayed.'], ['If the coroner is involved', 'Unexpected deaths are referred to the coroner. Tell them burial is urgent for religious reasons and ask for early release.'], ['Ghusl and kafan', 'The body is washed and shrouded, usually by trained volunteers of the same gender. Family can take part.'], ['Janazah salah', 'Four takbirs, standing: al-Fatihah, then salawat, then dua for the deceased, then dua for all Muslims, then salam. Add the notice in Janazah notices so the community comes.'], ['Burial', 'Carried to the grave, laid on the right side facing the qiblah. Stay a while and ask Allah to keep them firm in their questioning.'], ['The days after', 'Three days of mourning (4 months and 10 days for a widow). Neighbours bring food. Settle their debts, find any will (wasiyyah) and divide the estate by Islamic inheritance.']];
const KEEP = [['Water well or tap', 'Water is among the best sadaqah jariyah (Abu Dawud 1681: Sa‘d dug a well for his mother).', 'drop'], ['Quran and knowledge', 'Copies of the Quran, a scholarship, sponsoring a hifz student or a madrasah.', 'book'], ['A masjid or prayer space', 'Contribute to building or a carpet, a light, a wudu area.', 'dome'], ['Plant a tree', 'Whenever a person or animal eats from a tree you planted, it is charity for you (Bukhari 2320).', 'tree'], ['Feed people', 'Food parcels through Luton Foodbank or an iftar in their name.', 'bowl'], ['Hajj or Umrah for them', 'A woman asked if she could do Hajj for her mother who had vowed it; he said yes (Bukhari 1852). Do your own first.', 'kaaba'], ['A cause they cared about', 'Raise awareness of the illness they faced, or fundraise for the hospice that cared for them.', 'heart'], ['Their unpaid fasts or vows', 'Whoever dies owing fasts, their heir may fast for them (Bukhari 1952).', 'moon']];
const MYTH = [['Crying means weak faith.', 'The Prophet ﷺ cried. What is forbidden is wailing, tearing clothes and words of anger at Allah’s decree.'], ['You must hold events on the 3rd, 10th or 40th day.', 'These are cultural. The sunnah is dua, charity and visiting the family in the first days, not set gatherings or meals paid for by the grieving family.'], ['The family should feed everyone who visits.', 'The opposite: “Prepare food for the family of Ja‘far, for something has come to them that keeps them busy.” (Abu Dawud 3132)'], ['Don’t speak about the dead.', 'Speak of their good: “Mention the good of your dead and refrain from their faults.” (Tirmidhi 1019)'], ['Women can never go to the graveyard.', 'Scholars differ: many allow women to visit with dignity, without wailing. Ask your imam.'], ['Nothing reaches them once they’ve died.', 'Duas, charity, Hajj, fasts owed and paying their debts all reach them, by agreement of most scholars.']];
const DUAS_LOSS = () => dua('When you hear of a death or a loss', 'إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي وَأَخْلِفْ لِي خَيْرًا مِنْهَا', 'Inna lillahi wa inna ilayhi raji‘un. Allahumma’jurni fi musibati wa akhlif li khayran minha', 'To Allah we belong and to Him we return. O Allah, reward me in my loss and replace it with something better.', 'Muslim 918')
