const MOOD = { heavy: ['Heavy', 'Allah does not burden a soul beyond what it can bear.', 'Quran 2:286', 'Do one small thing today: eat something, step outside, pray one salah slowly.', 'Grief comes in waves. A heavy day doesn’t mean you’re going backwards.'],
  numb: ['Numb', 'The eyes shed tears and the heart grieves, and we say only what pleases our Lord.', 'Bukhari 1303', 'Tell one person how you actually are, even in a text.', 'Feeling nothing is common early on. It’s the mind protecting you, and it passes.'],
  angry: ['Angry', 'Yaqub said: “I only complain of my grief and sorrow to Allah.”', 'Quran 12:86', 'Pour it out to Allah in sujud, in your own words. That’s allowed.', 'Anger is a normal part of grief, at the illness, the hospital, even the person. Name it; don’t aim it at people.'],
  guilty: ['Guilty', 'Say: Allah decreed, and what He wills He does. “If only” opens the door to Shaytan.', 'Muslim 2664', 'Write down what you wish you’d said, then make dua for them instead.', 'Guilt is one of the most common feelings in grief, especially after a long illness. It doesn’t mean you failed them.'],
  sleep: ['Can’t sleep', 'Whoever recites Ayat al-Kursi at night has a protector from Allah until morning.', 'Bukhari 5010', 'Phone away, wudu, Ayat al-Kursi and the last three surahs, then lie on your right side.', 'Poor sleep is very common when grieving. If it lasts weeks, speak to your GP.'],
  okay: ['Okay today', 'Allah does not burden a soul beyond what it can bear.', 'Quran 2:286', 'Do one good deed for them today: a dua, a sadaqah, a kind word about them.', 'Feeling okay isn’t forgetting them. Joy and grief can sit side by side.'] };
