const BABYLOSS = [['h', 'Any Muslim who loses three children before they reach puberty, Allah will admit to Paradise by His mercy to them. Asked about two, he said: “And two.” In another narration, even one.', 'Bukhari 1248', SH('bukhari', 1248)], ['h', 'Your little ones are the little ones of Paradise. One meets his father and takes hold of his garment, and does not let go until Allah admits him and his father into Paradise.', 'Muslim 2635', SH('muslim', 2635)], ['h', 'By the One in whose hand is my soul, a miscarried baby will draw its mother into Paradise if she was patient and sought reward.', 'Ibn Majah 1609 (graded acceptable by some scholars)', SH('ibnmajah', 1609)], ['h', 'Patience is at the first strike of grief.', 'Bukhari 1302', SH('bukhari', 1302)], ['sc', 'Many scholars say a baby lost after four months of pregnancy is named, washed, shrouded and prayed over; before that, the baby is wrapped and buried respectfully without a janazah. Ask your imam: rulings differ slightly between schools.'], ['p', 'Losing a pregnancy before 24 weeks is the most common complication of pregnancy, affecting around one in five women in the UK. Fathers grieve too, often quietly.', 'Tommy’s / NHS', 'https://www.tommys.org/baby-loss-support'], ['c', 'Bereaved parents often say: give the baby a name, keep one thing (a scan, a blanket), and let people say the baby’s name.']];
