    research: [R('Helping at home builds the habit of seeing what needs doing. People who did chores as children were happier later in life.', 'Harvard Grant Study, via Lythcott-Haims', 'https://reviewed.com/parenting/features/expert-says-doing-chores-could-make-kids-more-successful-adults'), R('Forgiveness interventions reduce depression and stress and increase positive emotions.', 'Akhtar & Barlow meta-analysis', 'https://ora.ox.ac.uk/objects/uuid:c4f1e260-c0e9-4ff1-b858-030826eeefbd')],
