  $$('[data-fx]', node).forEach(c => c.onchange = () => { const k = 'lfFx_' + st.role + st.topic, d = store.get(k, {}); if (c.checked) d[c.dataset.fx] = 1; else delete d[c.dataset.fx]; store.set(k, d); if (navigator.vibrate) navigator.vibrate(6); });
  $$('[data-cpsay]', node).forEach(b => b.onclick = () => { X.copy(b.dataset.cpsay); b.textContent = 'Copied'; });
  $$('[data-qa]', node).forEach(b => b.onclick = () => { const [i, j] = b.dataset.qa.split(':').map(Number); st.qa[i] = j; if (navigator.vibrate) navigator.vibrate(QZ[i][1][j][1] ? [8, 30, 8] : 20); const y = (node.closest('.scr-body') || {}).scrollTop; redraw(); const sb = node.closest('.scr-body'); if (sb) sb.scrollTop = y; if (Object.keys(st.qa).length === QZ.length && X.burst) X.burst(); });
  const qr = $('[data-qreset]', node); if (qr) qr.onclick = () => { st.qa = {}; redraw(); };
